static void put(const char *root,const char *name,const char *text){char path[4096];assert(snprintf(path,sizeof(path),"%s/%s",root,name)>0);FILE *file=fopen(path,"wb");assert(file);assert(fwrite(text,1,strlen(text),file)==strlen(text));assert(!fclose(file));}
